package gg.neonnexus.smpplatform.integrations.skript;
import ch.njol.skript.lang.Effect; import ch.njol.skript.lang.Expression; import ch.njol.skript.lang.SkriptParser.ParseResult; import ch.njol.util.Kleenean; import org.bukkit.entity.Player; import org.bukkit.event.Event;
public final class EffNexusGuildEvent extends Effect { private Expression<String> name; private Expression<Player> players; @SuppressWarnings("unchecked") @Override public boolean init(Expression<?>[] x,int m,Kleenean d,ParseResult p){name=(Expression<String>)x[0];players=(Expression<Player>)x[1];return true;} @Override protected void execute(Event e){String eventName=name.getSingle(e);if(eventName!=null)for(Player p:players.getArray(e))NexusSkriptRegistry.bridge().createGuildEvent(p.getUniqueId(),eventName);} @Override public String toString(Event e,boolean d){return "nexus guild event";} }
